describe('shared chrome typography and grid', () => {
  it('switches every themed layer atomically without pausing persistent animations', () => {
    expect(styles).toContain('html[data-theme-switching="true"] .maria-app,html[data-theme-switching="true"] .maria-app *,html[data-theme-switching="true"] .maria-app *::before,html[data-theme-switching="true"] .maria-app *::after{transition:none!important}')
    expect(styles).not.toContain('html[data-theme-switching="true"] .maria-app *{animation:none')
  })

  it('keeps the browser root dark behind route transition snapshots', () => {
    expect(styles).toContain('html[data-theme="dark"],html[data-theme="dark"] body,html[data-theme="dark"] #root{background:#05070d}')
  })

  it('uses identical fixed-control sizing and offsets on every route', () => {
    expect(styles).toContain('.maria-header{position:fixed;z-index:40;left:24px;right:24px;top:24px;')
    expect(styles).toContain('font-size:clamp(14px,1vw,18px);white-space:nowrap;view-transition-name:fixed-header')
    expect(styles).toContain('.maria-avatar{width:42px;height:42px;overflow:hidden;border-radius:12px}')
    expect(styles).toContain('.maria-contact{display:flex;align-items:center;gap:3px;padding:10px 8px;border:0;background:transparent;')
    expect(styles).toContain('.maria-contact span{position:relative;top:-.08em;font-size:1.15em;line-height:1}')
    expect(styles).toContain('.maria-controls{position:fixed;z-index:40;left:24px;right:24px;bottom:24px;')
    expect(styles).toContain('font-size:16px;view-transition-name:fixed-controls')
    expect(styles).toContain('.maria-languages button{padding:4px 2px;opacity:.34;cursor:pointer}')
    expect(styles).toContain('.maria-theme button{width:24px;height:24px;display:grid;place-items:center;opacity:.34;cursor:pointer}')
    expect(styles).toContain('.maria-theme button img{display:block;max-width:100%;height:24px;object-fit:contain}')
    expect(styles).toContain('.theme-dark .maria-theme button img{filter:invert(1)}')
    expect(styles).toContain('.maria-languages .is-active,.maria-theme .is-active{opacity:1}')
    expect(styles).not.toContain('.maria-app:has(.maria-page)>.maria-header')
    expect(styles).not.toContain('.maria-app:has(.maria-page)>.maria-controls')
    expect(styles).toContain('.maria-header{grid-template-columns:auto 1fr auto;left:16px;right:16px;gap:10px}')
    expect(styles).toContain('.maria-controls{left:16px;right:16px}')
    expect(styles).toContain('.maria-header{grid-template-columns:34px 1fr auto;left:16px;right:16px;top:16px;column-gap:12px;row-gap:4px;font-size:15px}')
    expect(styles).toContain('.maria-avatar{grid-row:1/3;grid-column:1;align-self:center;width:34px;height:34px}')
    expect(styles).toContain('.maria-contact{grid-row:2;grid-column:3;justify-self:end;align-self:start;justify-content:flex-end;padding:0}.maria-contact span{display:inline;margin-left:0}')
    expect(styles).toContain('.maria-controls{left:16px;right:16px;bottom:16px;z-index:12;font-size:16.5px}')
    expect(styles).toContain('.maria-theme button{width:24px;height:24px}.maria-theme button img{height:24px}.maria-theme button:last-child img{height:26px}')
  })
})

describe('works hand entry and persistent fixed chrome', () => {
  it('lifts the hand from below while keeping shared controls above route transitions', () => {
    expect(styles).toContain('view-transition-name:works-hand')
    expect(styles).toContain('transform-origin:100% 54%')
    expect(styles).toContain('animation:maria-works-hand-enter .52s cubic-bezier(.2,.8,.2,1) both')
    expect(styles).toContain('@keyframes maria-works-hand-enter{from{transform:rotate(-48deg)}to{transform:rotate(0)}}')
    expect(styles).toContain('::view-transition-new(works-hand)')
    expect(styles).toContain('@keyframes maria-works-hand-enter-mobile{from{transform:rotate(-36deg)}to{transform:rotate(0)}}')
    expect(styles).toContain('view-transition-name:works-carousel')
    expect(styles).toContain('::view-transition-group(works-route),::view-transition-group(about-route){z-index:1}')
    expect(styles).toContain('::view-transition-group(works-hand){animation:none;z-index:2}')
    expect(styles).toContain('::view-transition-group(works-carousel){z-index:3}')
    expect(styles).toContain('view-transition-name:fixed-header')
    expect(styles).toContain('view-transition-name:fixed-controls')
    expect(styles).toContain('::view-transition-group(fixed-header),::view-transition-group(fixed-controls){animation:none;z-index:1000}')
    expect(styles).not.toContain('::view-transition-group(fixed-header),::view-transition-group(fixed-controls){animation-duration:.01ms')
    expect(styles).toContain('::view-transition-old(fixed-header),::view-transition-old(fixed-controls){animation:none;mix-blend-mode:normal}')
    expect(styles).toContain('::view-transition-new(fixed-header),::view-transition-new(fixed-controls){display:none}')
    expect(styles).toContain('::view-transition-new(works-hand){animation:none!important}')
  })
})

