describe('works centered corner ribbon', () => {
  it('wraps the next placeholder corner and keeps its tail gently moving while centered', () => {
    expect(styles).toContain('.works-corner-ribbon{position:absolute;z-index:9;right:-5%;top:-8%;width:48%;')
    expect(styles).toContain('.works-corner-ribbon__wrap{fill:none;stroke-linecap:round;stroke-dasharray:360;stroke-dashoffset:360')
    expect(styles).toContain('.maria-works-deck-card.is-centered .works-corner-ribbon__wrap{animation:works-ribbon-wrap .9s cubic-bezier(.2,.76,.22,1) forwards}')
    expect(styles).toContain('.maria-works-deck-card.is-centered .works-corner-ribbon__wrap--front{animation-delay:.18s}')
    expect(styles).toContain('.maria-works-deck-card.is-centered .works-corner-ribbon__tail{animation:works-ribbon-tail-in .38s ease-out .78s forwards,works-ribbon-sway 2.4s ease-in-out 1.16s infinite alternate}')
    expect(styles).toContain('@keyframes works-ribbon-wrap')
    expect(styles).toContain('@keyframes works-ribbon-sway')
    expect(styles).toContain('@media(prefers-reduced-motion:reduce){.works-corner-ribbon{display:none}}')
  })
})

